<script setup lang="ts">
import { localArticle, localFeed, localStories, portalFetch } from '~/composables/usePortal'
const route=useRoute();const slug=computed(()=>String(route.params.slug));const localStory=computed(()=>localArticle(slug.value));const article=await portalFetch(`/articles/${slug.value}`,localStory.value)
if(!article) throw createError({statusCode:404,statusMessage:'Texto não encontrado'})
const story=article as any
const hasCaptionedCover=computed(()=>Boolean(story.cover&&(/^https:\/\//i.test(story.cover)||story.cover.startsWith('/uploads/'))))
const related=localFeed({category:story.category_slug,pageSize:3}).articles.filter((item:any)=>item.slug!==story.slug).slice(0,3)
const socialImage=story.cover?.startsWith('https://')?story.cover:'https://pedeprosa.netlify.app/images/editorial/street-neighborhood.webp'
useSeoMeta({title:story.title,description:story.seo_description||story.excerpt,ogTitle:story.title,ogDescription:story.excerpt,ogType:'article',ogImage:socialImage,twitterImage:socialImage})
useHead({link:[{rel:'canonical',href:`https://pedeprosa.netlify.app/artigo/${story.slug}`}],meta:[{property:'article:published_time',content:story.published_at},{property:'article:author',content:story.author_name}]})
const copy=async()=>{try{await navigator.clipboard.writeText(window.location.href);copied.value=true;setTimeout(()=>copied.value=false,1800)}catch{}}
const copied=ref(false)
</script>

<template><article class="container article-page"><nav class="breadcrumbs" aria-label="Você está em"><NuxtLink to="/">Início</NuxtLink><span aria-hidden="true">/</span><NuxtLink :to="`/categoria/${story.category_slug}`">{{ story.category_name }}</NuxtLink></nav><header class="article-header"><NuxtLink class="eyebrow" :to="`/categoria/${story.category_slug}`">{{ story.category_name }}</NuxtLink><h1 class="article-title">{{ story.title }}</h1><p class="dek">{{ story.excerpt }}</p><div class="byline"><div class="byline-avatar" aria-hidden="true">{{ story.author_name.split(' ').map((n:string)=>n[0]).slice(0,2).join('') }}</div><div><strong><NuxtLink :to="`/autor/${story.author_slug}`">{{ story.author_name }}</NuxtLink></strong><span>{{ story.author_role || 'Repórter' }} · {{ story.author_location || 'Brasil' }}</span></div><div class="metadata byline-meta"><time :datetime="story.published_at">{{ new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(story.published_at)) }}</time><span class="dot">•</span><span>{{ story.reading_minutes }} min de leitura</span></div></div></header><figure class="article-cover"><ArticleArtwork :article="story"/><figcaption v-if="hasCaptionedCover">{{ story.alt_text }}</figcaption></figure><div class="article-layout"><aside class="article-tools"><button type="button" class="share-button" @click="copy">{{ copied?'Link copiado':'Compartilhar texto' }}</button><span class="reading-label">{{ story.reading_minutes }} min de leitura</span></aside><div class="article-body"><p v-for="(paragraph,index) in story.body" :key="index" :class="{first:index===0}">{{ paragraph }}</p><div class="article-tags"><span>Assuntos:</span><NuxtLink v-for="tag in story.tags" :key="tag" :to="`/tag/${tag.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-')}`">{{ tag }}</NuxtLink></div><div class="author-box"><div class="byline-avatar">{{ story.author_name.split(' ').map((n:string)=>n[0]).slice(0,2).join('') }}</div><div><span class="eyebrow">Sobre quem escreve</span><h2><NuxtLink :to="`/autor/${story.author_slug}`">{{ story.author_name }}</NuxtLink></h2><p>{{ story.author_bio }}</p><NuxtLink class="text-link" :to="`/autor/${story.author_slug}`">Ver todos os textos →</NuxtLink></div></div></div></div><section class="related"><div class="section-heading"><div><span class="section-kicker">Continue a leitura</span><h2>Mais desta editoria</h2></div><NuxtLink class="text-link" :to="`/categoria/${story.category_slug}`">Ver editoria →</NuxtLink></div><div class="article-grid"><ArticleCard v-for="item in related" :key="item.id" :article="item"/></div></section></article></template>

<style scoped>.article-page{max-width:1000px}.breadcrumbs{display:flex;gap:.6rem;padding:1.1rem 0;color:var(--muted);font-size:.75rem}.article-header{max-width:850px;margin:1.7rem auto 1.4rem;text-align:center}.article-title{font-size:clamp(2.5rem,6vw,5.2rem);margin:.8rem 0 1rem}.dek{font:1.18rem/1.48 var(--serif);color:#55564d;max-width:720px;margin:0 auto 1.5rem}.byline{display:flex;align-items:center;justify-content:center;gap:.8rem;text-align:left}.byline-avatar{width:44px;height:44px;border-radius:50%;background:#d9e0d5;color:var(--forest);display:grid;place-items:center;font:600 1rem var(--serif);flex:none}.byline strong,.byline span{display:block}.byline strong{font-size:.82rem}.byline span{font-size:.69rem;color:var(--muted)}.byline-meta{margin-left:1rem}.article-cover{margin:1.8rem 0 2rem}.article-cover :deep(.cover-art){aspect-ratio:2.05;min-height:340px}.article-cover figcaption{text-align:right;font-size:.68rem;color:var(--muted);margin-top:.45rem}.article-layout{display:grid;grid-template-columns:150px minmax(0,680px);justify-content:center;gap:2rem}.article-tools{display:flex;flex-direction:column;gap:.5rem;align-items:flex-start}.share-button{border:1px solid var(--line);background:transparent;padding:.5rem .7rem;color:var(--forest);font-size:.72rem;font-weight:700;cursor:pointer}.reading-label{font-size:.7rem;color:var(--muted)}.article-body{font:1.13rem/1.85 var(--serif)}.article-body p{margin:0 0 1.35rem}.article-body p.first:first-letter{float:left;font:600 4.3rem/.8 var(--serif);color:var(--rust);padding:.1rem .45rem 0 0}.article-tags{display:flex;flex-wrap:wrap;gap:.45rem;margin:2rem 0}.article-tags span{font:700 .75rem var(--sans);align-self:center}.article-tags a{border:1px solid var(--line);border-radius:99px;padding:.25rem .65rem;font:600 .7rem var(--sans);color:var(--forest)}.author-box{display:grid;grid-template-columns:48px 1fr;gap:1rem;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:1.2rem 0;margin:2rem 0}.author-box h2{font:600 1.2rem var(--serif);margin:.2rem 0}.author-box p{font: .84rem/1.5 var(--sans);color:var(--muted);margin:.3rem 0}.related{padding-top:2rem}@media(max-width:700px){.article-title{font-size:2.6rem}.byline{flex-wrap:wrap;justify-content:start;max-width:380px;margin:auto}.byline-meta{width:100%;margin-left:3.25rem}.article-cover :deep(.cover-art){aspect-ratio:1.3;min-height:230px}.article-layout{display:block}.article-tools{flex-direction:row;align-items:center;margin:0 0 1rem}.article-body{font-size:1.04rem}}
</style>
